-- ----------------------------
-- Table structure for sys_menu
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_menu";
CREATE TABLE "public"."sys_menu" (
  "id" int8 NOT NULL,
  "title" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "name" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "path" varchar(200) COLLATE "pg_catalog"."default",
  "sort" int4 NOT NULL,
  "icon" varchar(128) COLLATE "pg_catalog"."default",
  "type" int4 NOT NULL,
  "component" varchar(256) COLLATE "pg_catalog"."default",
  "perms" varchar(128) COLLATE "pg_catalog"."default",
  "status" int4 NOT NULL,
  "display" int4 NOT NULL,
  "cache" int4 NOT NULL,
  "link" text COLLATE "pg_catalog"."default",
  "remark" text COLLATE "pg_catalog"."default",
  "parent_id" int8,
  "created_time" timestamptz(6) NOT NULL,
  "updated_time" timestamptz(6),
  "deleted" int8 NOT NULL DEFAULT '0'::bigint,
  "deleted_time" timestamptz(6)
)
;
COMMENT ON COLUMN "public"."sys_menu"."id" IS '雪花算法主键 ID';
COMMENT ON COLUMN "public"."sys_menu"."title" IS '菜单标题';
COMMENT ON COLUMN "public"."sys_menu"."name" IS '菜单名称';
COMMENT ON COLUMN "public"."sys_menu"."path" IS '路由地址';
COMMENT ON COLUMN "public"."sys_menu"."sort" IS '排序';
COMMENT ON COLUMN "public"."sys_menu"."icon" IS '菜单图标';
COMMENT ON COLUMN "public"."sys_menu"."type" IS '菜单类型（0目录 1菜单 2按钮 3内嵌 4外链）';
COMMENT ON COLUMN "public"."sys_menu"."component" IS '组件路径';
COMMENT ON COLUMN "public"."sys_menu"."perms" IS '权限标识';
COMMENT ON COLUMN "public"."sys_menu"."status" IS '菜单状态（0停用 1正常）';
COMMENT ON COLUMN "public"."sys_menu"."display" IS '是否显示（0否 1是）';
COMMENT ON COLUMN "public"."sys_menu"."cache" IS '是否缓存（0否 1是）';
COMMENT ON COLUMN "public"."sys_menu"."link" IS '外链地址';
COMMENT ON COLUMN "public"."sys_menu"."remark" IS '备注';
COMMENT ON COLUMN "public"."sys_menu"."parent_id" IS '父菜单ID';
COMMENT ON COLUMN "public"."sys_menu"."created_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_menu"."updated_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_menu"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON COLUMN "public"."sys_menu"."deleted_time" IS '删除时间';
COMMENT ON TABLE "public"."sys_menu" IS '菜单表';

