-- ----------------------------
-- Table structure for sys_notice
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_notice";
CREATE TABLE "public"."sys_notice" (
  "id" int8 NOT NULL,
  "title" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "type" int4 NOT NULL,
  "status" int4 NOT NULL,
  "content" text COLLATE "pg_catalog"."default" NOT NULL,
  "created_time" timestamptz(6) NOT NULL,
  "updated_time" timestamptz(6),
  "deleted" int8 NOT NULL DEFAULT '0'::bigint,
  "deleted_time" timestamptz(6)
)
;
COMMENT ON COLUMN "public"."sys_notice"."id" IS '雪花算法主键 ID';
COMMENT ON COLUMN "public"."sys_notice"."title" IS '标题';
COMMENT ON COLUMN "public"."sys_notice"."type" IS '类型（0：通知、1：公告）';
COMMENT ON COLUMN "public"."sys_notice"."status" IS '状态（0：隐藏、1：显示）';
COMMENT ON COLUMN "public"."sys_notice"."content" IS '内容';
COMMENT ON COLUMN "public"."sys_notice"."created_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_notice"."updated_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_notice"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON COLUMN "public"."sys_notice"."deleted_time" IS '删除时间';
COMMENT ON TABLE "public"."sys_notice" IS '系统通知公告表';

-- ----------------------------
-- Records of sys_notice
-- ----------------------------
