-- ----------------------------
-- Table structure for sys_opera_log
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_opera_log";
CREATE TABLE "public"."sys_opera_log" (
  "id" int8 NOT NULL,
  "trace_id" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "username" varchar(64) COLLATE "pg_catalog"."default",
  "method" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "title" varchar(256) COLLATE "pg_catalog"."default" NOT NULL,
  "path" varchar(512) COLLATE "pg_catalog"."default" NOT NULL,
  "ip" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "country" varchar(64) COLLATE "pg_catalog"."default",
  "region" varchar(64) COLLATE "pg_catalog"."default",
  "city" varchar(64) COLLATE "pg_catalog"."default",
  "user_agent" varchar(512) COLLATE "pg_catalog"."default",
  "os" varchar(64) COLLATE "pg_catalog"."default",
  "browser" varchar(64) COLLATE "pg_catalog"."default",
  "device" varchar(64) COLLATE "pg_catalog"."default",
  "args" json,
  "status" int4 NOT NULL,
  "code" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "msg" text COLLATE "pg_catalog"."default",
  "cost_time" float8 NOT NULL,
  "opera_time" timestamptz(6) NOT NULL,
  "created_time" timestamptz(6) NOT NULL
)
;
COMMENT ON COLUMN "public"."sys_opera_log"."id" IS '雪花算法主键 ID';
COMMENT ON COLUMN "public"."sys_opera_log"."trace_id" IS '请求跟踪 ID';
COMMENT ON COLUMN "public"."sys_opera_log"."username" IS '用户名';
COMMENT ON COLUMN "public"."sys_opera_log"."method" IS '请求方法';
COMMENT ON COLUMN "public"."sys_opera_log"."title" IS '操作模块';
COMMENT ON COLUMN "public"."sys_opera_log"."path" IS '请求路径';
COMMENT ON COLUMN "public"."sys_opera_log"."ip" IS 'IP 地址';
COMMENT ON COLUMN "public"."sys_opera_log"."country" IS '国家';
COMMENT ON COLUMN "public"."sys_opera_log"."region" IS '地区';
COMMENT ON COLUMN "public"."sys_opera_log"."city" IS '城市';
COMMENT ON COLUMN "public"."sys_opera_log"."user_agent" IS '用户代理';
COMMENT ON COLUMN "public"."sys_opera_log"."os" IS '操作系统';
COMMENT ON COLUMN "public"."sys_opera_log"."browser" IS '浏览器';
COMMENT ON COLUMN "public"."sys_opera_log"."device" IS '设备';
COMMENT ON COLUMN "public"."sys_opera_log"."args" IS '请求参数';
COMMENT ON COLUMN "public"."sys_opera_log"."status" IS '操作状态（0异常 1正常）';
COMMENT ON COLUMN "public"."sys_opera_log"."code" IS '操作状态码';
COMMENT ON COLUMN "public"."sys_opera_log"."msg" IS '提示消息';
COMMENT ON COLUMN "public"."sys_opera_log"."cost_time" IS '请求耗时（ms）';
COMMENT ON COLUMN "public"."sys_opera_log"."opera_time" IS '操作时间';
COMMENT ON COLUMN "public"."sys_opera_log"."created_time" IS '创建时间';
COMMENT ON TABLE "public"."sys_opera_log" IS '操作日志表';

