-- Table structure for sys_role
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_role";
CREATE TABLE "public"."sys_role" (
  "id" int8 NOT NULL,
  "name" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "status" int4 NOT NULL,
  "is_filter_scopes" bool NOT NULL,
  "remark" text COLLATE "pg_catalog"."default",
  "created_time" timestamptz(6) NOT NULL,
  "updated_time" timestamptz(6),
  "deleted" int8 NOT NULL DEFAULT '0'::bigint,
  "deleted_time" timestamptz(6)
)
;
COMMENT ON COLUMN "public"."sys_role"."id" IS '雪花算法主键 ID';
COMMENT ON COLUMN "public"."sys_role"."name" IS '角色名称';
COMMENT ON COLUMN "public"."sys_role"."status" IS '角色状态（0停用 1正常）';
COMMENT ON COLUMN "public"."sys_role"."is_filter_scopes" IS '过滤数据权限(0否 1是)';
COMMENT ON COLUMN "public"."sys_role"."remark" IS '备注';
COMMENT ON COLUMN "public"."sys_role"."created_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_role"."updated_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_role"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON COLUMN "public"."sys_role"."deleted_time" IS '删除时间';
COMMENT ON TABLE "public"."sys_role" IS '角色表';

