-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS "public"."sys_user";
CREATE TABLE "public"."sys_user" (
  "id" int8 NOT NULL,
  "uuid" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "username" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "nickname" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "password" varchar(256) COLLATE "pg_catalog"."default",
  "salt" bytea,
  "email" varchar(256) COLLATE "pg_catalog"."default",
  "phone" varchar(11) COLLATE "pg_catalog"."default",
  "avatar" varchar(256) COLLATE "pg_catalog"."default",
  "status" int4 NOT NULL,
  "is_superuser" bool NOT NULL,
  "is_staff" bool NOT NULL,
  "is_multi_login" bool NOT NULL,
  "join_time" timestamptz(6) NOT NULL,
  "last_login_time" timestamptz(6),
  "last_password_changed_time" timestamptz(6),
  "dept_id" int8,
  "created_time" timestamptz(6) NOT NULL,
  "updated_time" timestamptz(6),
  "deleted" int8 NOT NULL DEFAULT '0'::bigint,
  "deleted_time" timestamptz(6)
)
;
COMMENT ON COLUMN "public"."sys_user"."id" IS '雪花算法主键 ID';
COMMENT ON COLUMN "public"."sys_user"."username" IS '用户名';
COMMENT ON COLUMN "public"."sys_user"."nickname" IS '昵称';
COMMENT ON COLUMN "public"."sys_user"."password" IS '密码';
COMMENT ON COLUMN "public"."sys_user"."salt" IS '加密盐';
COMMENT ON COLUMN "public"."sys_user"."email" IS '邮箱';
COMMENT ON COLUMN "public"."sys_user"."phone" IS '手机号';
COMMENT ON COLUMN "public"."sys_user"."avatar" IS '头像';
COMMENT ON COLUMN "public"."sys_user"."status" IS '用户账号状态(0停用 1正常)';
COMMENT ON COLUMN "public"."sys_user"."is_superuser" IS '超级权限(0否 1是)';
COMMENT ON COLUMN "public"."sys_user"."is_staff" IS '后台管理登陆(0否 1是)';
COMMENT ON COLUMN "public"."sys_user"."is_multi_login" IS '是否重复登陆(0否 1是)';
COMMENT ON COLUMN "public"."sys_user"."join_time" IS '注册时间';
COMMENT ON COLUMN "public"."sys_user"."last_login_time" IS '上次登录时间';
COMMENT ON COLUMN "public"."sys_user"."last_password_changed_time" IS '上次密码变更时间';
COMMENT ON COLUMN "public"."sys_user"."dept_id" IS '部门关联ID';
COMMENT ON COLUMN "public"."sys_user"."created_time" IS '创建时间';
COMMENT ON COLUMN "public"."sys_user"."updated_time" IS '更新时间';
COMMENT ON COLUMN "public"."sys_user"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON COLUMN "public"."sys_user"."deleted_time" IS '删除时间';
COMMENT ON TABLE "public"."sys_user" IS '用户表';

