-- ----------------------------
-- Table structure for task_scheduler
-- ----------------------------
DROP TABLE IF EXISTS "public"."task_scheduler";
CREATE TABLE "public"."task_scheduler" (
  "id" int8 NOT NULL,
  "name" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "task" varchar(256) COLLATE "pg_catalog"."default" NOT NULL,
  "args" json,
  "kwargs" json,
  "queue" varchar(256) COLLATE "pg_catalog"."default",
  "exchange" varchar(256) COLLATE "pg_catalog"."default",
  "routing_key" varchar(256) COLLATE "pg_catalog"."default",
  "start_time" timestamptz(6),
  "expire_time" timestamptz(6),
  "expire_seconds" int4,
  "type" int4 NOT NULL,
  "interval_every" int4,
  "interval_period" varchar(256) COLLATE "pg_catalog"."default",
  "crontab" varchar(64) COLLATE "pg_catalog"."default",
  "one_off" bool NOT NULL,
  "status" int4 NOT NULL,
  "total_run_count" int4 NOT NULL,
  "last_run_time" timestamptz(6),
  "remark" text COLLATE "pg_catalog"."default",
  "created_time" timestamptz(6) NOT NULL,
  "updated_time" timestamptz(6),
  "deleted" int8 NOT NULL DEFAULT '0'::bigint,
  "deleted_time" timestamptz(6)
)
;
COMMENT ON COLUMN "public"."task_scheduler"."id" IS '雪花算法主键 ID';
COMMENT ON COLUMN "public"."task_scheduler"."name" IS '任务名称';
COMMENT ON COLUMN "public"."task_scheduler"."task" IS '要运行的 Celery 任务';
COMMENT ON COLUMN "public"."task_scheduler"."args" IS '任务可接收的位置参数';
COMMENT ON COLUMN "public"."task_scheduler"."kwargs" IS '任务可接收的关键字参数';
COMMENT ON COLUMN "public"."task_scheduler"."queue" IS 'CELERY_TASK_QUEUES 中定义的队列';
COMMENT ON COLUMN "public"."task_scheduler"."exchange" IS '低级别 AMQP 路由的交换机';
COMMENT ON COLUMN "public"."task_scheduler"."routing_key" IS '低级别 AMQP 路由的路由密钥';
COMMENT ON COLUMN "public"."task_scheduler"."start_time" IS '任务开始触发的时间';
COMMENT ON COLUMN "public"."task_scheduler"."expire_time" IS '任务不再触发的截止时间';
COMMENT ON COLUMN "public"."task_scheduler"."expire_seconds" IS '任务不再触发的秒数时间差';
COMMENT ON COLUMN "public"."task_scheduler"."type" IS '调度类型（0间隔 1定时）';
COMMENT ON COLUMN "public"."task_scheduler"."interval_every" IS '任务再次运行前的间隔周期数';
COMMENT ON COLUMN "public"."task_scheduler"."interval_period" IS '任务运行之间的周期类型';
COMMENT ON COLUMN "public"."task_scheduler"."crontab" IS 'Crontab 表达式';
COMMENT ON COLUMN "public"."task_scheduler"."one_off" IS '是否仅运行一次';
COMMENT ON COLUMN "public"."task_scheduler"."status" IS '状态（0停用 1正常）';
COMMENT ON COLUMN "public"."task_scheduler"."total_run_count" IS '任务触发的总次数';
COMMENT ON COLUMN "public"."task_scheduler"."last_run_time" IS '任务最后触发的时间';
COMMENT ON COLUMN "public"."task_scheduler"."remark" IS '备注';
COMMENT ON COLUMN "public"."task_scheduler"."created_time" IS '创建时间';
COMMENT ON COLUMN "public"."task_scheduler"."updated_time" IS '更新时间';
COMMENT ON COLUMN "public"."task_scheduler"."deleted" IS '是否已删除（0：否；id：是）';
COMMENT ON COLUMN "public"."task_scheduler"."deleted_time" IS '删除时间';
COMMENT ON TABLE "public"."task_scheduler" IS '任务调度表';

